/**
 * @event
 * @name scwin.grd_noticeList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_noticeList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_noticeList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_noticeList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (typeof scwin.fileDownload === 'function') { scwin.fileDownload(r["sprtRoomNo"], r["attachSeq"], r["attachFileNm"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fileDownload (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fileDownload'); } return; } 
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_noticeList.oncellclick' });
    }
};


