/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_pageIndex
 * @returns
 * @hidden N
*/
scwin.search = async function (ipt_pageIndex) {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_startDate', $('#searchForm')).val())) {
        await $c.win.alert("시작일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_endDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_endDate', $('#searchForm')).val())) {
        await $c.win.alert("종료일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && $('#ipt_endDate', $('#searchForm')).val() !== "" && $('#ipt_startDate', $('#searchForm')).val() > $('#ipt_endDate', $('#searchForm')).val()) {
        await $c.win.alert("시작일자는 종료일자 이전 이여야 합니다.");
        return;
    }
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldstf76300/jldstf76300.xml");
    $('#ipt_method', $('#searchForm')).val("readNoticeList");
    $c.util.getComponent('ipt_ldMktTpCd').setValue($('#slc_selLdMktTpCd option:selected').val());
    $('#searchForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
